INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "きょうか", 120601, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 0, 0, 3, 120601, 465, 0, 0, 180801, 0, "2015/04/01 15:00:00", "キョウカ（リトルリリカル）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しぇふぃ", 120701, 1.84, 120701, "【物理】前衛で、雪花舞う晴れ空をゆく新春氷竜少女。\nＵＢで顕現させる氷竜の牙で味方への強化スキルを高め\n自身の範囲攻撃技と共に苛烈な攻勢で敵陣を凍滅する。", 120701, 1, 0, 0, "2026/01/31 11:59:59", 0, 1, 0, 4, 22, 3, 120701, 283, 1, 450, 0, 0, "2026/01/15 12:00:00", "シェフィ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "るか", 120801, 1.3, 120801, "【物理】前衛で雪月花の舞を納める新春の姉御。\n攻撃を当てる度に増加する【剣の刻印】でＵＢとスキルの\n威力を上昇させ、目にも止まらぬ斬撃で敵を圧倒する。", 120801, 2, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 4, 22, 1, 120801, 193, 1, 450, 0, 0, "2023/10/16 15:00:00", "ルカ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "いりや", 120901, 1.425, 120901, "【魔法】中衛で自らの血を代償に力を振るう新春吸血鬼。\n自身のＨＰを消費して放つ強力なスキルと、敵からＴＰを\n吸収するスキルを自在に操り、目の前の敵を撃滅する。", 120901, 12, 0, 0, "2026/01/31 11:59:59", 0, 1, 0, 3, 38, 3, 120901, 424, 2, 450, 0, 0, "2026/01/15 12:00:00", "イリヤ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぺこりーぬ", 121001, 2.25, 121001, "【物理】前衛で、仲間との絆を力に変え戦う腹ペコ王女。\n敵のＨＰ状態で永続の物理攻撃力上昇と、短時間の特大\n攻撃力上昇＆自己ＴＰ回復を使い分け戦況を一変させる。", 121001, 1, 0, 0, "2026/02/09 11:59:59", 0, 1, 0, 5, 41, 3, 121001, 164, 1, 450, 0, 0, "2026/01/31 12:00:00", "ペコリーヌ（オーバーロード）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "きゃる", 121101, 2.07, 121101, "【魔法】中衛で仲間との絆を力に変え戦うツンデレ猫娘。\n敵を妨害するスキルと、ＵＢで敵全体を恐慌状態にし既に\n恐慌状態の敵のＴＰをダウンさせ、全戦場を掌握する。", 121101, 1, 0, 0, "2026/02/09 11:59:59", 0, 1, 0, 7, 42, 3, 121101, 588, 2, 450, 0, 0, "2026/01/31 12:00:00", "キャル（オーバーロード）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らびりすた", 121201, 1.55, 121201, "【物理】前衛で世界の理をすべて見つめる『迷宮女王』。\n味方を攻撃面で強化し、継続ＨＰ回復を全体に付与する\nスキルで戦線を整え、自身も圧倒的な力で敵を殲滅する。", 121201, 6, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 4, 40, 1, 121201, 260, 1, 450, 0, 0, "2023/11/16 15:00:00", "ラビリスタ（オーバーロード）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くるみ", 121301, 1.9, 121301, "【物理】後衛で、皆のため意を決し奮起する小さな女優。\n残りＨＰが多いほど物理攻撃力がアップし、物理攻撃無効\nバリアのスキルやＨＰ・ＴＰ継続回復で味方を支援する。", 121301, 3, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 3, 3, 3, 121301, 731, 1, 450, 0, 0, "2022/03/03 19:00:00", "クルミ（ステージ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "みさき", 121401, 2.27, 121401, "【魔法】後衛で後ろの味方を強化する魔法少女の看板娘。\n後衛の味方をバリアとＴＰ継続回復で支援し、自分の魔法\n攻撃力に応じ強化される攻撃力アップスキルで鼓舞する。", 121401, 15, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 7, 3, 121401, 742, 2, 450, 0, 0, "2022/03/15 15:00:00", "ミサキ（ステージ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あゆみ", 121501, 2.0, 121501, "【物理】中衛で、闇夜に身を潜める神出鬼没の怪盗少女。\n敵の目の前から姿を消す隠密スキルや、遠くの敵に対する\nＴＰダウンスキルを駆使して、敵陣後方から瓦解させる。", 121501, 12, 0, 0, "2026/04/15 11:59:59", 0, 1, 0, 6, 6, 3, 121501, 590, 1, 450, 0, 0, "2026/03/31 12:00:00", "アユミ（怪盗）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "いのり", 121601, 1.425, 121601, "【物理】前衛で闇に紛れ会心の一撃を放つ怪盗ドラゴン。\n隠密効果中、ダメージが大アップし必ずクリティカルする\nＵＢとスキルを駆使し安定したダメージを敵に叩き込む。", 121601, 17, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 3, 3, 3, 121601, 292, 1, 450, 0, 0, "2022/04/15 15:00:00", "イノリ（怪盗）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "あきの", 121701, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 0, 0, 3, 121701, 421, 0, 0, 180901, 0, "2015/04/01 15:00:00", "アキノ（アキノ＆サレン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "されん", 121801, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 0, 0, 3, 121801, 421, 0, 0, 180901, 0, "2015/04/01 15:00:00", "サレン（アキノ＆サレン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あんな", 121901, 2.125, 121901, "【魔法】前衛で己を鼓舞し高めた魔力を放つ蒼海の冥姫。\n発動の度、攻撃力とクリティカル時ダメージが上昇する\nＵＢと自己犠牲を払う強力な範囲攻撃技で敵を撃滅する。", 121901, 12, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 5, 5, 3, 121901, 293, 2, 450, 0, 0, "2022/05/15 15:00:00", "アンナ（パイレーツ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しのぶ", 122001, 1.425, 122001, "【物理】中衛で、彷徨える魂を解き放つ海星の霊能少女。\n攻撃の際、付与する【霊錨の刻印】を駆使し、ダメージ量\nアップのスキルと防御力ダウンのＵＢで敵を浄滅へ導く。", 122001, 14, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 3, 3, 3, 122001, 380, 1, 450, 0, 0, "2022/05/03 19:00:00", "シノブ（パイレーツ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あおい", 122101, 1.97, 122101, "【物理】後衛で百千の矢を放つ、ぼっちの山籠りエルフ。\n物理魔法無効バリアで耐え凌ぎ、敵全体への射撃と自分の\n間合いに入った敵への強力な弓雨の追撃で掃討する。", 122101, 9, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 35, 35, 1, 122101, 731, 1, 450, 0, 0, "2024/04/18 15:00:00", "アオイ（キャンプ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆかり", 122201, 1.84, 122201, "【物理】中衛で最高の一杯を自然と共に愉しむ元聖騎士。\n【至福のひと時】が増えるほどに、味方の物理攻撃力や\nクリティカル時のダメージを強力に強化し、勝利を掴む。", 122201, 8, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 4, 4, 3, 122201, 419, 1, 450, 0, 0, "2022/05/31 12:00:00", "ユカリ（キャンプ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "うぁんぴぃ", 122301, 1.425, 122301, "【魔法】中衛で、幼き竜と共に歩むさいきょーの吸血姫。\n味方全体の強化と、敵のＴＰを吸収するスキルで力を蓄え\nＵＢ発動後ベスと共闘し防御ダウンと強撃で攻勢に出る。", 122301, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 43, 43, 3, 122301, 564, 2, 450, 0, 0, "2022/06/15 15:00:00", "ヴァンピィ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ひより", 122401, 2.42, 122401, "【物理】前衛で皆にエールを送り鼓舞する真夏の元気娘。\n味方のＨＰを継続回復し行動速度アップの他、味方の数に\n応じてクリティカル強化と攻撃力を引き上げ勝利に導く。", 122401, 8, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 1, 122401, 264, 1, 450, 0, 0, "2024/06/17 15:00:00", "ヒヨリ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "れい", 122501, 1.965, 122501, "【物理】前衛で水刃の加護を纏い水面を駆ける渚の剣士。\nクリティカル時のダメージを底上げしＵＢ発動の度、纏う\n【水刃の加護】で全スキルダメージを上げ、敵陣を穿つ。", 122501, 0, 0, 0, "2026/08/31 11:59:59", 0, 1, 0, 4, 4, 3, 122501, 250, 1, 450, 0, 0, "2026/08/26 12:00:00", "レイ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆい", 122601, 2.27, 122601, "【魔法】中衛で、魔法キャラを補助する夜凪の魔法士。\n累積する攻撃強化スキルとＴＰ回復、物魔両面の無効\nバリアや継続ＨＰ回復で攻守共に味方を支え勝利へ導く。", 122601, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 7, 3, 122601, 554, 2, 450, 0, 0, "2022/07/15 15:00:00", "ユイ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "きょうか", 122701, 1.92, 122701, "【魔法】後衛で、難しい魔法の練習に励む海辺の優等生。\nランダムな敵に当たるスキルの威力は攻撃の際に付与する\n【バタフライシール】で増幅し、防御力もダウンさせる。", 122701, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 7, 3, 122701, 812, 2, 450, 0, 0, "2022/08/15 15:00:00", "キョウカ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "みそぎ", 122801, 2.295, 122801, "【物理】前衛で敵後方に花火を仕掛ける夜涼みの悪戯娘。\n敵の最前衛をスタンで足止めしつつ、最後衛を中心とした\nＵＢで狭範囲の敵を引き寄せ、ＴＰダウンで攻勢を阻む。", 122801, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 1, 122801, 237, 1, 450, 0, 0, "2024/07/16 15:00:00", "ミソギ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "みみ", 122901, 2.25, 122901, "【物理】中衛で巨大バルーンと跳ね回る夏色うさぎっこ。\nＵＢやスキルで全てのマルチターゲットに追加ダメージを\n与え、自己強化と防御力ダウンで強敵のブレイクを狙う。", 122901, 0, 0, 0, "2026/08/31 11:59:59", 0, 1, 0, 5, 5, 3, 122901, 361, 1, 450, 0, 0, "2026/08/26 12:00:00", "ミミ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あめす", 123001, 2.27, 123001, "【魔法】後衛で、新たな姿で騎士の冒険を支える妖精。\nダメージカットや防御力アップ、無効バリアで味方を護り\nバリアを起点とする攻撃力とＴＰの支援で攻勢に転ずる。", 123001, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 44, 44, 3, 123001, 746, 2, 450, 0, 0, "2026/08/23 12:00:00", "アメス");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "まほ", 123101, 1.795, 123101, "【魔法】後衛でぬいぐるみ達と大冒険に挑むマホ隊員。\n味方に付与する【ふわふわウール】は被ダメージ時に消費\nされＴＰを回復し、一気呵成の反撃で活路を切り拓く。", 123101, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 7, 3, 123101, 793, 2, 450, 0, 0, "2022/09/03 19:00:00", "マホ（エクスプローラー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あやね", 123201, 1.425, 123201, "【物理】前衛で、相棒と困難を越え猛進するアヤネ隊員。\n群る敵を二つの範囲攻撃で一気に捉え、周囲の味方の物理\n攻撃力とクリティカルアップで冒険を阻む壁を打ち崩す。", 123201, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 3, 3, 3, 123201, 256, 1, 450, 0, 0, "2022/09/15 15:00:00", "アヤネ（エクスプローラー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ねあ", 123301, 1.62, 123301, "【物理】中衛で粘液を振りまくキイロいスライムギャル。\nスキルで敵全体の物理攻撃能力やＴＰ上昇を低下させ、\nＵＢでスライム化し全敵を攻撃しつつ無敵ボディを得る。", 123301, 0, 0, 0, "2026/09/30 11:59:59", 0, 1, 0, 1, 0, 3, 123301, 350, 1, 450, 0, 0, "2026/09/22 12:00:00", "ネア");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "じゅん", 123401, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 5, 5, 3, 123401, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "ジュン（キャンプ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "りん", 123501, 2.34, 123501, "【物理】中衛で敵を悪戯で翻弄する恐怖のキョンシー娘。\n最も魔法攻撃力が高い敵に急襲を仕掛け、ＴＰ減少や魔法\n攻撃力ダウン、スタン等の妨害スキルで機先を制する。", 123501, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 6, 6, 1, 123501, 583, 1, 450, 0, 0, "2024/09/17 15:00:00", "リン（ハロウィン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "とも", 123601, 1.965, 123601, "【物理】前衛で、同志と力を合わせ共に戦う夜廻り剣士。\n自分と物理攻撃力が最も高い味方１キャラの攻撃力を大幅\nに上昇させ、目にもとまらぬ剣技で不届き者を成敗する。", 123601, 0, 0, 0, "2025/11/30 11:59:59", 0, 1, 0, 4, 4, 3, 123601, 262, 1, 450, 0, 0, "2025/11/14 15:00:00", "トモ（ハロウィン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ななか", 123701, 2.07, 123701, "【魔法】後衛で、オタ活に精を出すハロウィン魔法少女。\nＨＰ回復量ダウンで敵の戦略を崩し、ダメージフィールド\nと対象の数で火傷の威力を増す熱狂の炎が敵を包み込む。", 123701, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 21, 3, 123701, 741, 2, 450, 0, 0, "2022/10/15 15:00:00", "ナナカ（ハロウィン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くりすてぃーな", 123801, 2.295, 123801, "【物理】前衛で、戦場を跳ね回るラビット姿の誓約女君。\n物理攻撃を全て回避するスキルと攻撃力の強化で敵陣に\n単身特攻をかけ、ＵＢの範囲攻撃で敵を内から薙ぎ倒す。", 123801, 0, 0, 0, "2025/11/14 14:59:59", 0, 1, 0, 1, 1, 3, 123801, 238, 1, 450, 0, 0, "2025/11/03 12:00:00", "クリスティーナ（ワイルド）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "まつり", 123901, 2.125, 123901, "【物理】前衛で母製の鎧を纏い気合い上々の獣人族騎士。\n自分のＨＰが低いほど与えるダメージと無効バリアの耐久\n力を高め、防御力ダウンと永続攻撃アップで活路を拓く。", 123901, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 2, 2, 3, 123901, 183, 1, 450, 0, 0, "2022/11/15 15:00:00", "マツリ（ワイルド）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あかり", 124001, 2.07, 124001, "【魔法】中衛で、聖夜の街に幸せを運ぶ双子の妹サンタ。\n自分の魔法攻撃力に応じて効果が上がる味方全体への攻撃\n力強化に加え、単体特大魔法攻撃で勝利の旋律を奏でる。", 124001, 0, 0, 0, "2025/12/31 11:59:59", 0, 1, 0, 7, 7, 3, 124001, 438, 2, 450, 0, 0, "2025/12/21 12:00:00", "アカリ（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "より", 124101, 1.965, 124101, "【魔法】中衛で、光を灯し幸せを届ける双子の姉サンタ。\n最も近い１キャラの魔法攻撃力や行動速度アップ、ＴＰの\n回復に加え、全員を支援するスキルで聖夜の勝利を飾る。", 124101, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 6, 6, 1, 124101, 433, 2, 450, 0, 0, "2024/11/16 15:00:00", "ヨリ（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "じゅん", 124201, 2.07, 124201, "【物理】前衛で、味方を庇護し祝福する聖白の騎士団長。\nスキルで後方の味方の攻撃能力を強化、ＴＰを回復させ、\n防御力ダウンと自分のＨＰを回復するＵＢで勝機を掴む。", 124201, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 5, 5, 3, 124201, 144, 1, 450, 0, 0, "2022/12/23 12:00:00", "ジュン（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "あん", 124301, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 0, 0, 3, 124301, 577, 0, 0, 181001, 0, "2015/04/01 15:00:00", "アン（アン＆グレア）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "ぐれあ", 124401, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 0, 0, 3, 124401, 577, 0, 0, 181001, 0, "2015/04/01 15:00:00", "グレア（アン＆グレア）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ほまれ", 124501, 2.07, 124501, "【魔法】後衛で、魔力を笑顔に隠す晴れ着姿の龍の首魁。\n自分の攻撃強化とＴＰ回復をし、ＵＢで放つ曙光の落涙は\n敵数で威力と防御力の減少量を上げ、全ての災厄を祓う。", 124501, 0, 0, 0, "2026/01/31 11:59:59", 0, 1, 0, 7, 21, 3, 124501, 707, 2, 450, 0, 0, "2026/01/15 12:00:00", "ホマレ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "みさと", 124601, 2.44, 124601, "【魔法】後衛で真心重ねて味方をもてなす仲居姿の先生。\n全スキルで味方の物理攻撃力とクリティカル能力を上げ、\n魔防やＴＰ上昇の支援とＨＰ、ＴＰの回復で万福を願う。", 124601, 0, 0, 0, "2026/01/31 11:59:59", 0, 1, 0, 7, 21, 3, 124601, 698, 2, 450, 0, 0, "2026/01/15 12:00:00", "ミサト（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "みつき", 124701, 2.24, 124701, "【物理】中衛で、振袖姿で旅館に手を貸す隻眼の闇医者。\n朧ろ状態にした敵への攻撃時、スキルのダメージや防御力\nのダウン値が上昇し、紫煙に捉えた敵を艶然と討ち取る。", 124701, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 7, 46, 1, 124701, 590, 1, 450, 0, 0, "2024/12/16 15:00:00", "ミツキ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "のぞみ", 124801, 2.14, 124801, "【物理】中衛で、未来を信じ希望を灯すトップアイドル。\nバトル開始時に物理キャラのＴＰ特大回復と敵の永続物防\nダウンで加勢し、物理攻撃強化とＴＰ回復で勝利へ導く。", 124801, 0, 0, 0, "2026/02/09 11:59:59", 0, 1, 0, 4, 0, 3, 124801, 423, 1, 450, 0, 0, "2026/01/31 12:00:00", "ノゾミ（リベレイター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "かや", 124901, 1.965, 124901, "【物理】前衛で先陣を切り未来を掴む喧嘩屋ドラゴン族。\n初弾が大幅強化するスキルで自分の攻撃力とＴＰを大きく\n高め、威力を増したＵＢで先制し群がる敵を薙ぎ払う。", 124901, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 0, 1, 124901, 170, 1, 450, 0, 0, "2025/01/16 15:00:00", "カヤ（リベレイター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "むいみ", 125001, 1.965, 125001, "【物理】前衛で、相棒と共に明日へと進む大悪党の少女。\n自己強化や物防ダウンを駆使するムイミと、ＵＢ後に一定\n時間共闘するオクトーの追撃で、輝く未来を取り戻す。", 125001, 0, 0, 0, "2026/02/09 11:59:59", 0, 1, 0, 5, 0, 3, 125001, 221, 1, 450, 0, 0, "2026/01/31 12:00:00", "ムイミ（リベレイター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "たまき", 125101, 2.24, 125101, "【物理】後衛から客を癒しもてなす猫カフェ店員の猫娘。\n物攻の高いキャラの傍で周囲の物攻アップやＨＰとＴＰを\n回復し、周囲の味方数で強化される攻撃で敵を一掃する。", 125101, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 8, 47, 3, 125101, 825, 1, 450, 0, 0, "2023/03/03 19:00:00", "タマキ（カフェ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "もにか", 125201, 1.965, 125201, "【物理】中衛で、駄菓子を振舞い福を蒔く猫カフェ店員。\n攻撃を３回受けるまで味方全体の物理攻撃力を極大アップ\nさせ、２種の物防ダウンスキルで序盤を一気に加勢する。", 125201, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 4, 4, 3, 125201, 463, 1, 450, 0, 0, "2023/03/10 12:00:00", "モニカ（カフェ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "こっころ", 125301, 2.07, 125301, "【物理】後衛で、わんわんと一緒の新緑レンジャー少女。\n自分の攻撃力に応じて強化される物理攻撃支援スキルや\nＨＰ継続回復、バリアで周囲を支え、絆の勝利へと導く。", 125301, 0, 0, 0, "2026/04/15 11:59:59", 0, 1, 0, 6, 6, 3, 125301, 752, 1, 450, 0, 0, "2026/03/31 12:00:00", "コッコロ（レンジャー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しおり", 125401, 2.09, 125401, "【物理】後衛で、相棒と共に山を駆ける新米レンジャー。\nスキルで自分の攻撃力とクリティカル時のダメージを上げ\nＴＰを回復し、ダメージと防御力ダウンで敵を追い込む。", 125401, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 8, 8, 3, 125401, 710, 1, 450, 0, 0, "2023/04/10 12:00:00", "シオリ（レンジャー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "じーた", 125501, 1.92, 125501, "【魔法】中衛で、他の術者と魔力を束ねる究竟の魔導士。\n味方への魔法攻撃支援とＴＰ回復に加え、敵陣の攻防両面\nの弱体化で戦況を整え、自らも強力な攻撃魔法を放つ。", 125501, 0, 0, 0, "2026/05/31 11:59:59", 0, 1, 0, 7, 50, 3, 125501, 443, 2, 450, 0, 0, "2026/05/22 12:00:00", "ジータ（ウォーロック）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "びから", 125601, 2.09, 125601, "【物理】前衛で夢と希望とネズ耳を届ける鼠神宮の巫女。\n周囲の味方の物理攻撃支援、ＴＰ上昇アップと回復で援護\nし、自身の無敵化で敵の隙を突き鋭い金牙の一撃を放つ。", 125601, 0, 0, 0, "2026/05/31 11:59:59", 0, 1, 0, 51, 0, 3, 125601, 267, 1, 450, 0, 0, "2026/05/22 12:00:00", "ビカラ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "かりん", 125701, 2.24, 125701, "【魔法】中衛で森羅万象を究め味方を支援する錬金術師。\n物理、魔法の属性を問わない敵の弱体化と味方の強化に加\nえ、スキルによる高頻度のＨＰ回復で盤石な戦局を築く。", 125701, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 7, 9, 1, 125701, 579, 2, 450, 0, 0, "2025/04/16 15:00:00", "カリン（アルケミスト）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "りり", 125801, 2.09, 125801, "【物理】中衛で、黒羽の力を使い空を制する嘆鎌の少女。\nバトル開始時に、敵の範囲攻撃を躱す【飛行】状態となり\n生成したシャドウと共に、眼前の敵を一薙ぎに斬り払う。", 125801, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 3, 0, 3, 125801, 464, 1, 450, 0, 0, "2023/04/17 12:00:00", "リリ（フォールン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "かや", 125901, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 3, 125901, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "カヤ（リベレイター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くりあ", 126001, 2.09, 126001, "【物理】中衛から、我が身を盾に味方を守る隠棘の少女。\nバトル開始時【飛行】し、最もＨＰの低い味方をかばい、\n味方のＨＰに応じて強化されるスキルで敵を牽制する。", 126001, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 0, 0, 3, 126001, 406, 1, 450, 0, 0, "2023/10/31 12:00:00", "クリア（フォールン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぷれしあ", 126101, 2.09, 126101, "【魔法】中衛で、マイペースに味方を支える破杖の少女。\n【飛行】し、クリティカルの強化やＨＰ・ＴＰ回復で味方\nを支援し、魔法攻撃力を加えた物理攻撃で敵を平らげる。", 126101, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 44, 53, 3, 126101, 480, 2, 450, 0, 0, "2023/11/15 15:00:00", "プレシア（フォールン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "いりや", 126201, 2.09, 126201, "【魔法】中衛で、眷属と永久の血盟を誓う月下の吸血鬼。\nＵＢで眷属を２体喚び、味方への攻撃支援や行動速度上昇\nで強化し、眷属と共に見舞う猛攻で前途を阻む敵を討つ。", 126201, 0, 0, 0, "2026/06/30 11:59:59", 0, 1, 0, 3, 3, 3, 126201, 568, 2, 450, 0, 0, "2026/06/22 12:00:00", "イリヤ（儀装束）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆき", 126301, 2.07, 126301, "【魔法】中衛で、闇色の儀装束を纏う「美を統べる者」。\nステータスアップ効果を受け【美貌】を増し、魔法攻撃力\nダウンや味方の強化、ＴＰ回復の効果を高めて解き放つ。", 126301, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 9, 3, 126301, 456, 2, 450, 0, 0, "2023/06/15 15:00:00", "ユキ（儀装束）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くろーちぇ", 126401, 2.09, 126401, "【物理】中衛で着脱可能な鉄腕を放つ機械人族のロボ娘。\nＵＢ発動で【フルチャージ】状態になり、【バッテリー】\nが切れるまで強化スキルを連発し、一帯を超速圧砕する。", 126401, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 1, 1, 3, 126401, 373, 1, 450, 0, 0, "2026/08/23 12:00:00", "クローチェ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らいらえる", 126501, 1.965, 126501, "【魔法】後衛で優美にほほ笑むジオ・テオゴニアの姫君。\n開始時に発動する【界雷】で、敵味方に影響を与えつつ、\n魔法防御ダウンと強力なダメージスキルで裁きを下す。", 126501, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 7, 0, 3, 126501, 740, 2, 450, 0, 0, "2026/08/23 12:00:00", "ライラエル");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ねねか", 126601, 2.04, 126601, "【魔法】後衛で、涼しげに微笑む夏色姿の『変貌大妃』。\nスキルで味方を大幅に強化し、最も魔法攻撃力が高い味方\nの魔法攻撃力を写し取った攻撃力で、強力なＵＢを放つ。", 126601, 0, 0, 0, "2026/07/31 11:59:59", 0, 1, 0, 7, 7, 3, 126601, 650, 2, 450, 0, 0, "2026/07/15 12:00:00", "ネネカ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あきの", 126701, 1.965, 126701, "【物理】前衛で、優雅なバカンスを過ごす夕映えの令嬢。\n敵が魔法攻撃をする場合に効果を大幅に上げる２種の範囲\n攻撃と攻防両面の支援スキルで、盛夏の勝鬨を上げる。", 126701, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 5, 5, 1, 126701, 224, 1, 450, 0, 0, "2025/06/17 15:00:00", "アキノ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆかり", 126801, 1.97, 126801, "【物理】前衛で、夏の麦しゅわを嗜むビーチの元聖騎士。\n敵単体にダメージを与えながら、周囲の味方への魔法無効\nバリア付与と魔防アップで守りを固めて勝利の波に乗る。", 126801, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 5, 5, 3, 126801, 159, 1, 450, 0, 0, "2023/07/15 15:00:00", "ユカリ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らんふぁ", 126901, 1.965, 126901, "【魔法】後衛で、密やかな潮騒に耳を傾ける晩陽の歌姫。\n魔法クリティカルの極大アップを筆頭に攻防両面で周囲の\n味方を強化し、さらに自身もＵＢで数多の敵を退かせる。", 126901, 0, 0, 0, "2026/08/31 11:59:59", 0, 1, 0, 7, 21, 3, 126901, 682, 2, 450, 0, 0, "2026/08/26 12:00:00", "ランファ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くうか", 127001, 1.97, 127001, "【物理】前衛で新たな刺激を追い求める水着姿のドＭ娘。\n自分のＨＰが下がるほど効果量が上昇するスキルの物理攻\n撃力アップとＵＢのダメージで、勝利の大海へ飛び込む。", 127001, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 2, 52, 1, 127001, 133, 1, 450, 0, 0, "2025/07/16 15:00:00", "クウカ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しのぶ", 127101, 2.09, 127101, "【物理】前衛で、穏やかな水面に揺蕩う夜光の霊能少女。\n召喚した親父に敵の攻撃を引き付けさせつつ、シノブ自身\nの攻撃性能強化と防御ダウンを扱い、敵を冥海へと誘う。", 127101, 0, 0, 0, "2026/08/31 11:59:59", 0, 1, 0, 5, 46, 3, 127101, 255, 1, 450, 0, 0, "2026/08/26 12:00:00", "シノブ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "きゃる", 127201, 2.09, 127201, "【魔法】後衛で、制服姿に胸を高鳴らせるアオハル猫娘。\n攻防両面のサポートに加え行動速度アップとＴＰ回復で味\n方を支援し、最も遠くの敵を狙うＵＢで輝く勝利を得る。", 127201, 0, 0, 0, "2025/09/30 11:59:59", 0, 1, 0, 7, 7, 3, 127201, 804, 2, 450, 0, 0, "2025/09/16 15:00:00", "キャル（編入生）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "すずな", 127301, 2.09, 127301, "【物理】後衛でもにカワ制服を着こなすカリスマモデル。\nクリティカル時に味方を強化するスキルや、追加ダメージ\nが発生するＵＢによって青春の一ページを切り取る。", 127301, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 8, 8, 3, 127301, 750, 1, 450, 0, 0, "2023/09/15 15:00:00", "スズナ（編入生）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "びから", 127401, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 3, 127401, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "ビカラ（コラボ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "されん", 127501, 2.09, 127501, "【物理】中衛で、優艶に炎と踊り舞う情熱のサレンママ。\n物理攻撃から味方を守り、【炎舞の刻印】の数に応じて効\n果の上がる物攻アップとＴＰ回復で皆を奮い立たせる。", 127501, 0, 0, 0, "2026/02/09 11:59:59", 0, 1, 0, 4, 4, 3, 127501, 304, 1, 450, 0, 0, "2026/01/31 12:00:00", "サレン（サラサリア）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "るか", 127601, 1.965, 127601, "【物理】前衛で、空飛ぶ絨毯で巡り回るオアシスの姉御。\n自分の物防を大幅に高めて敵を挑発するスキルと敵のＴＰ\nとＴＰ上昇をダウンさせるＵＢで、爽やかに勝利を掴む。", 127601, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 4, 4, 3, 127601, 157, 1, 450, 0, 0, "2023/10/15 15:00:00", "ルカ（サラサリア）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "りんど", 127701, 1.965, 127701, "【魔法】後衛で、メイド業に奔走する双子ドラゴンの姉。\nＵＢのフィールド展開中は攻撃、防御、ＴＰ回復と多彩な\n支援スキルの効果が再発動し味方を手厚くサポートする。", 127701, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 6, 48, 3, 127701, 693, 2, 450, 0, 0, "2024/10/10 12:00:00", "リンド");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "うるむ", 127801, 1.965, 127801, "【魔法】後衛で、文句を言いつつ働く双子ドラゴンの妹。\nダメージと魔法防御力ダウンを両立するスキルを持つが、\n目を離すと【サボりの誘惑】に負け、手を抜いてしまう。", 127801, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 47, 3, 127801, 706, 2, 450, 0, 0, "2024/10/18 12:00:00", "ヴルム");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぺこりーぬ", 127901, 1.965, 127901, "【魔法】中衛でみんなに笑顔を届ける腹ペコサンタ王女。\n前線で敵の攻撃を耐えながら範囲内の味方の防御サポート\nと敵の防御ダウンまでこなし、聖夜に勝利の輝きを灯す。", 127901, 0, 0, 0, "2025/12/31 11:59:59", 0, 1, 0, 5, 5, 3, 127901, 372, 2, 450, 0, 0, "2025/12/21 12:00:00", "ペコリーヌ（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くれじった", 128001, 2.09, 128001, "【物理】後衛で、甘美なひと時を堪能する聖夜の女商人。\n最も遠い味方へのＴＰ回復や、初弾に追加効果のある攻撃\nで敵の弱体化と味方の強化を行い、勝利の舞台を整える。", 128001, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 35, 35, 3, 128001, 723, 1, 450, 0, 0, "2023/12/15 15:00:00", "クレジッタ（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "しずる", 128101, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 0, 0, 3, 128101, 580, 0, 0, 181101, 0, "2015/04/01 15:00:00", "シズル（シズル&リノ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "りの", 128201, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 0, 0, 3, 128201, 580, 0, 0, 181101, 0, "2015/04/01 15:00:00", "リノ（シズル&リノ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "いのり", 128301, 2.09, 128301, "【物理】前衛で相手をからかうお調子者の年神ドラゴン。\n敵全体を挑発し、敵の妨害スキルにカウンターして前方の\n敵すべてをスタンさせるスキルで戦局を引っ掻き回す。", 128301, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 3, 38, 1, 128301, 191, 1, 450, 0, 0, "2026/01/16 15:00:00", "イノリ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "はつね", 128401, 2.09, 128401, "【魔法】後衛で特別な景色を共にする初夢超能力ガール。\n敵が物理攻撃を行う場合、攻撃性能の強化に加えて複数の\n弱体効果が追加され、攻守ともに味方を支援し敵を掃う。", 128401, 0, 0, 0, "2026/01/31 11:59:59", 0, 1, 0, 7, 21, 3, 128401, 801, 2, 450, 0, 0, "2026/01/15 12:00:00", "ハツネ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "かすみ", 128501, 2.09, 128501, "【魔法】後衛で、絵馬に秘めた願いを祷る新年の名探偵。\n敵と味方の数で効果量が上昇するダメージと攻撃力支援に\n加え、２種類の回復スキルを使いこなして勝利を願う。", 128501, 0, 0, 0, "2026/01/31 11:59:59", 0, 1, 0, 7, 21, 3, 128501, 739, 2, 450, 0, 0, "2026/01/15 12:00:00", "カスミ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "りり", 128601, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 3, 128601, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "リリ（フォールン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ひより", 128701, 2.09, 128701, "【物理】前衛で、煌炎宿し希望を振りまく覚醒の元気娘。\n放つ炎は敵を攻守ともに弱化させて同時に味方を鼓舞し、\n２種のＴＰ回復効果で攻勢を絶やさず勝利を呼び込む。", 128701, 0, 0, 0, "2026/02/09 11:59:59", 0, 1, 0, 1, 0, 3, 128701, 226, 1, 450, 0, 0, "2026/01/31 12:00:00", "ヒヨリ（アストラル）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "れい", 128801, 1.965, 128801, "【物理】前衛で、旋風を纏い未来へ駆ける覚醒の剣士。\n目にも止まらぬ速さの剣技で敵を吹き飛ばしスタンさせ、\n仲間の守りを固めるスキルを駆使し勝利の道を切り開く。", 128801, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 4, 0, 1, 128801, 194, 1, 450, 0, 0, "2025/08/16 15:00:00", "レイ（アストラル）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆい", 128901, 2.09, 128901, "【魔法】後衛で、願いを力に極光を放つ覚醒の魔法士。\n自分を強化しながら高火力魔法を絶えず撃ち込み、バリア\nを起点とした味方への攻撃支援スキルで勝利を手にする。", 128901, 0, 0, 0, "2026/02/09 11:59:59", 0, 1, 0, 7, 0, 3, 128901, 772, 2, 450, 0, 0, "2026/01/31 12:00:00", "ユイ（アストラル）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "えりす", 129001, 2.09, 129001, "【魔法】後衛で、眠りから目覚め美しく咲き誇る黒薔薇。\n終焉を超えし【回帰の薔薇】と、行動速度アップを始めと\nした多種の攻防支援で味方を強化し、新たな未来を掴む。", 129001, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 7, 0, 3, 129001, 800, 2, 450, 0, 0, "2026/08/23 12:00:00", "エリス");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆに", 129301, 2.09, 129301, "【物理】後衛で、退廃的な冬の学びに溺れる水際の才媛。\n物理攻撃の強化、回復、行動速度アップで味方を支援し、\nＵＢで得た【水際の安寧】を死守するため膂力を振るう。", 129301, 0, 0, 0, "2026/03/31 11:59:59", 0, 1, 0, 7, 7, 3, 129301, 708, 1, 450, 0, 0, "2026/03/16 10:00:00", "ユニ（ウィンター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くろえ", 129401, 2.09, 129401, "【物理】前衛で、水面に映る神速のダウナー系水着女子。\n攻撃を当てる度に敵に付与する【水月】の数に応じて物防\nダウンやダメージの効果が上昇し、必勝の抜き手を切る。", 129401, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 2, 2, 3, 129401, 188, 1, 450, 0, 0, "2024/03/18 12:00:00", "クロエ（ウィンター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ちえる", 129501, 2.09, 129501, "【物理】前衛で、ちぇるっとちぇるるな水着のちえるん。\nステータスアップで溜まる【ちぇる】を、自身の火力や\n支援能力に還元して、真冬の真夏をちぇらるれれぽぱぴ？", 129501, 0, 0, 0, "2025/12/15 14:59:59", 0, 1, 0, 1, 1, 3, 129501, 247, 1, 450, 0, 0, "2025/11/30 12:00:00", "チエル（ウィンター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あねもね", 129601, 2.09, 129601, "【物理】中衛で怜悧麗花の陣を張るアルラウネの妖魔人。\n敵の攻撃力、防御力、与ダメージを下げ、ＴＰを吸収し、\nＵＢの継続ダメージで領域を侵す敵を絶えず拒み退ける。", 129601, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 129601, 550, 1, 450, 0, 0, "2026/08/23 12:00:00", "アネモネ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ねふぃーねら", 129701, 2.09, 129701, "【物理】中衛で万魔の頂点に君臨するジオ・ゲヘナの媛。\n環境効果【妨魔塵】で魔法攻撃を阻害し、行動速度アップ\n等の支援や苛烈な攻撃で無謀な不届き者を平伏させる。", 129701, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 129701, 540, 1, 450, 0, 0, "2026/08/23 12:00:00", "ネフィ＝ネラ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "まこと", 129801, 2.09, 129801, "【物理】前衛で、情と熱意で仲間を束ねる指揮官の狼娘。\n敵の攻守を削りつつ、自分のＴＰ回復や対象が物防ダウン\n状態の時に発生する追撃で猛攻を仕掛け前線を突破する。", 129801, 0, 0, 0, "2026/04/15 11:59:59", 0, 1, 0, 5, 5, 3, 129801, 269, 1, 450, 0, 0, "2026/03/31 12:00:00", "マコト（コマンダー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "えりこ", 129901, 1.84, 129901, "【物理】前衛で、苛烈な教えで味方を率いる狂恋の教官。\nＴＰ回復や防御支援に加え味方の人数で効果アップする攻\n撃支援と大ダメージで、味方全体を奮い立たせ敵を破る。", 129901, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 6, 48, 3, 129901, 294, 1, 450, 0, 0, "2024/04/15 15:00:00", "エリコ（コマンダー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "やまと", 130001, 2.09, 130001, "【物理】前衛で、豪胆にスリルを嗜む盗賊ギルドの長女。\n最前線で命を張りながら、獲得した【バンディダイス】の\n消費によって自らを大幅強化し、有象無象を地に伏せる。", 130001, 0, 0, 0, "2025/11/14 14:59:59", 0, 1, 0, 4, 0, 3, 130001, 150, 1, 450, 0, 0, "2025/11/03 12:00:00", "ヤマト");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "わかな", 130101, 2.09, 130101, "【物理】中衛の、貧乏クジを引きがちな盗賊ギルド次女。\n召喚したスキッドがワカナをかばって前線に立ち、自身は\n攻撃支援にＨＰとＴＰ回復まで、献身的に味方を支える。", 130101, 0, 0, 0, "2025/11/14 14:59:59", 0, 1, 0, 7, 9, 3, 130101, 535, 1, 450, 0, 0, "2025/11/03 12:00:00", "ワカナ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ふぶき", 130201, 1.84, 130201, "【物理】中衛の、ナマイキで超天才な盗賊ギルドの三女。\n【味方バリアー♡】で自分へのダメージを味方に押し付け\nＨＰ最大でダメージアップする範囲攻撃で敵を蹂躙する。", 130201, 0, 0, 0, "2025/11/14 14:59:59", 0, 1, 0, 5, 0, 3, 130201, 371, 1, 450, 0, 0, "2025/11/03 12:00:00", "フブキ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "れい", 130601, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 4, 1, 3, 130601, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "レイ（アストラル）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "きょうか", 130701, 1.92, 130701, "【魔法】中衛で、お花畑に春を届ける花衣装の優等生。\nスキル発動回数に応じた効率的な自己強化やクリティカル\n時の追加効果を持つスキルとＵＢで勝利の風を吹かせる。", 130701, 0, 0, 0, "2026/05/31 11:59:59", 0, 1, 0, 7, 7, 3, 130701, 563, 2, 450, 0, 0, "2026/05/22 12:00:00", "キョウカ（スプリング）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "すずめ", 130801, 1.84, 130801, "【魔法】中衛で、春に彩られた花衣装のドジっ娘メイド。\n範囲内の敵にダメージを与えながら、多数の弱体化効果を\n持つスキルやＵＢを駆使して、穏やかに吹く勝利を掴む。", 130801, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 7, 3, 130801, 558, 2, 450, 0, 0, "2024/05/15 15:00:00", "スズメ（スプリング）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くるる", 130901, 2.09, 130901, "【魔法】中衛で、皆を夢の世界に誘う宝石兎族の支配人。\nステータスアップ効果を受けるたびに【かばばん君】を増\nやし、反射的に味方へ攻撃支援の恩返しをしてしまう。", 130901, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 7, 3, 130901, 440, 2, 450, 0, 0, "2024/06/15 15:00:00", "クルル");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "まほ", 131001, 1.84, 131001, "【魔法】後衛で、サーカスの舞台に輝くメルヘン少女。\n味方の攻防支援や敵の攻防弱体化の他【カーテンコール】\n付与時の追加ダメージスキルで、勝利のライトを照らす。", 131001, 0, 0, 0, "2026/06/30 11:59:59", 0, 1, 0, 7, 7, 3, 131001, 702, 2, 450, 0, 0, "2026/06/22 12:00:00", "マホ（ドリームパーク）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ねあ", 131101, 2.09, 131101, "【物理】前衛でハグの機会を窺う水着のスライムギャル。\n攻撃してきた敵に【ネバネバ】を自動で付着させ、攻撃力\nダウンやダメージ、束縛など複数の効果を引き起こす。", 131101, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 2, 52, 3, 131101, 165, 1, 450, 0, 0, "2024/06/30 12:00:00", "ネア（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "みそら", 131201, 2.09, 131201, "【魔法】後衛で夏の盛りにイイコトをする溌溂水着少女★\n【PSI★ストーム】をチャージし、連続攻撃で敵を殲滅し\nて、継続ＴＰ回復やバリアで抜け目なく味方を支援する。", 131201, 0, 0, 0, "2026/07/31 11:59:59", 0, 1, 0, 54, 54, 3, 131201, 753, 2, 450, 0, 0, "2026/07/15 12:00:00", "ミソラ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "りり", 131301, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 3, 131301, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "リリ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "くりあ", 131401, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 3, 131401, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "クリア");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "ぷれしあ", 131501, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 3, 131501, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "プレシア");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "りり", 131601, 1.92, 131601, "【物理】中衛で、夏の陽光のもと研鑽する妹系大和撫子。\n防御力アップに加えバリアやＨＰ回復で味方の守りを固め\nＴＰ回復や攻撃力ダウンをも巧みに操り、場を支配する。", 131601, 0, 0, 0, "2026/07/31 11:59:59", 0, 1, 0, 4, 4, 3, 131601, 399, 1, 450, 0, 0, "2026/07/15 12:00:00", "リリ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あめす", 131701, 1.92, 131701, "【魔法】後衛で、黄昏の水面に舞い降りる水着姿の妖精。\n行動速度アップやＴＰ支援をはじめとした多数のサポート\nを施しつつ、ＵＢの攻防弱体化で清爽に勝利へと導く。", 131701, 0, 0, 0, "2026/08/31 11:59:59", 0, 1, 0, 44, 53, 3, 131701, 743, 2, 450, 0, 0, "2026/08/26 12:00:00", "アメス（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ほまれ", 131801, 2.09, 131801, "【魔法】後衛で夏の清涼に翼を休める水着姿の龍の首領。\n攻防弱体化に加え、ステータスダウン付与のたび増加する\n【日食】の数に応じたダメージで、抗う全てを灰に帰す。", 131801, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 21, 3, 131801, 709, 2, 450, 0, 0, "2024/08/15 15:00:00", "ホマレ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "えみりあ", 131901, 2.09, 131901, "【魔法】後衛で、パックと共に戦う真夏のハーフエルフ。\n氷壁を生成するスキルや、強力なダメージと速度ダウンを\n付与するユニオンバーストで、敵の侵攻を食い止める。", 131901, 0, 0, 1, "2030/12/31 15:00:00", 0, 1, 0, 7, 23, 1, 131901, 725, 2, 450, 0, 0, "2024/08/31 12:00:00", "エミリア（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "えきどな", 132001, 2.09, 132001, "【魔法】後衛で未知の世界との邂逅に胸躍る強欲の魔女。\n鮮烈な攻撃魔法をはじめ、味方への攻撃支援、敵の弱体化\nから自己蘇生まで、あらゆる魔法を振るい、欲を満たす。", 132001, 0, 0, 1, "2025/10/24 11:59:59", 0, 1, 0, 7, 21, 3, 132001, 775, 2, 450, 0, 0, "2025/10/10 12:00:00", "エキドナ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "れむ", 132101, 2.09, 132101, "【物理】前衛で夏の日差しの中、余暇を楽しむ双子の妹。\nＵＢで鬼族の力を解放すると攻防両面に加えＨＰ吸収が\n上昇し、目に映る全てを【狂騒】のままに叩き伏せる。", 132101, 0, 0, 1, "2025/10/24 11:59:59", 0, 1, 0, 13, 24, 3, 132101, 146, 1, 450, 0, 0, "2025/10/10 12:00:00", "レム（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "のぞみ", 132201, 1.84, 132201, "【魔法】後衛で、希望を錬成するアルケミストアイドル。\n【錬金素材】から【パフューム】を創り、ダメージに加え\nＴＰ回復や攻撃支援能力を向上させて勝利の香りを運ぶ。", 132201, 0, 0, 0, "2025/10/31 11:59:59", 0, 1, 0, 7, 7, 3, 132201, 721, 2, 450, 0, 0, "2025/10/24 12:00:00", "ノゾミ（アルケミスト）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "るいずまりー", 132301, 2.09, 132301, "【魔法】後衛で、底知れぬ叡智を秘めた天才錬金術師。\n高い方の防御力でダメージを受ける調和状態を付与し、\n２回まで性能が上昇していくＵＢで、妄想を爆発させる。", 132301, 0, 0, 0, "2026/05/22 11:59:59", 0, 1, 0, 7, 7, 3, 132301, 754, 2, 450, 0, 0, "2026/05/11 12:00:00", "ルイズマリー");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "いろは", 132401, 2.09, 132401, "【物理】中衛で、大きな体で無邪気に遊び回る天才剣士。\n戦いの中で【剣圧】を溜め、その後のスキルやＵＢで物防\n一定無視のダメージを連発し、才気煥発の活躍を見せる。", 132401, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 5, 0, 3, 132401, 501, 1, 450, 0, 0, "2025/06/20 12:00:00", "イロハ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "その", 132501, 2.09, 132501, "【魔法】後衛で、小柄で大人対応な錬金堂の省エネ店主。\n強力な弱体効果を与えながら、デバフ付与のたび増加する\n【虚脱】が80溜まると本気を出し定時厳守で戦い抜く。", 132501, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 23, 3, 132501, 636, 2, 450, 0, 0, "2025/05/15 15:00:00", "ソノ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らいらえる", 132801, 2.09, 132801, "【魔法】後衛で、雪白の肌を黒衣に包んだ甘美なる姫君。\n味方のＨＰを代償に強力なバリアを展開しつつ、バリアを\n起点とした高出力の二連撃で、聖夜の大樹に灯を点す。", 132801, 0, 0, 0, "2025/12/15 14:59:59", 0, 1, 0, 7, 0, 3, 132801, 750, 2, 450, 0, 0, "2025/11/30 12:00:00", "ライラエル（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "いお", 132901, 2.09, 132901, "【魔法】後衛で、心地良い眠りの中に訪れる聖夜の悪魔。\n最も魔法攻撃力が高い味方に【悪魔の口づけ】を付与し、\n攻撃支援とＴＰ回復による付きっきりの手ほどきをする。", 132901, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 5, 46, 3, 132901, 748, 2, 450, 0, 0, "2024/12/09 12:00:00", "イオ（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぐれいす", 133001, 2.09, 133001, "【物理】前衛で、宙を舞うように戦う幽霊の守護騎士。\nＵＢで味方の攻撃と速度支援を行い、【レイスボディ】で\n敵の目を逃れ、不意を突く一撃で永遠の眠りにつかせる。", 133001, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 133001, 234, 1, 450, 0, 0, "2026/08/23 12:00:00", "グレイス");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "うぁいおれっと", 133101, 1.75, 133101, "【物理】前衛で、儚くも凛と咲くジオ・ニヴルヘルの姫。\n継続ダメージ効果を鈍化させる環境効果【忌火】で盾に、\n絶怠霊度の継続割合攻撃で矛となり、静寂の冥府を護る。", 133101, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 133101, 154, 1, 450, 0, 0, "2026/08/23 12:00:00", "ヴァイオレット");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "もにか", 133201, 2.09, 133201, "【物理】前衛で、元日も元気にはしゃぎまわる軍人少女。\n与ダメージに応じて追加効果が強化されるＵＢと、発動ご\nとに成長する自己強化スキルで秩序を乱す者の目を回す。", 133201, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 4, 22, 1, 133201, 296, 1, 450, 0, 0, "2024/12/31 12:00:00", "モニカ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "されん", 133501, 2.09, 133501, "【魔法】後衛で、傍らで心を重ねる振袖姿の救護院の主。\n味方へのＴＰ回復の支援をしつつ、味方がＵＢを発動する\nたびダメージが上がるスキルで、共に困難を乗り越える。", 133501, 0, 0, 0, "2026/01/15 11:59:59", 0, 1, 0, 4, 22, 3, 133501, 718, 2, 450, 0, 0, "2026/01/03 12:00:00", "サレン（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "めどぅーさ", 133601, 2.09, 133601, "【物理】中衛で眷属と力を合わせて戦う誇り高き蛇乙女。\n【魔眼】の数に応じて効果量が上がるスキルのダメージと\n弱体化で範囲内の敵を追い詰め、鋭い瞳で石へと変える。", 133601, 0, 0, 0, "2026/01/15 11:59:59", 0, 1, 0, 0, 0, 3, 133601, 445, 1, 450, 0, 0, "2026/01/03 12:00:00", "メドゥーサ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らびりすた", 133701, 2.09, 133701, "【魔法】後衛で、始原の冠装を使いこなす『迷宮女王』。\n水属性の味方のＴＰ上昇を増加する領域を作り、連射攻撃\nで敵の防御を撃ち抜くことで七冠の力を敵に知らしめる。", 133701, 0, 0, 0, "2026/02/15 11:59:59", 0, 1, 0, 8, 0, 3, 133701, 717, 2, 450, 0, 0, "2026/02/09 12:00:00", "ラビリスタ（アルファ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ねねか", 133801, 2.09, 133801, "【魔法】後衛から、始原の姿で戦況を操る『変貌大妃』。\n召喚したグレゴールから攻撃支援とＴＰ回復を受け、互い\nの魔力を合わせた連携攻撃で、幽玄なる玉座に君臨する。", 133801, 0, 0, 0, "2026/02/15 11:59:59", 0, 1, 0, 7, 0, 3, 133801, 759, 2, 450, 0, 0, "2026/02/09 12:00:00", "ネネカ（アルファ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くりすてぃーな", 133901, 2.09, 133901, "【物理】前衛で、始原の冠装の力を振るう『誓約女君』。\n10行動目に攻撃力を大幅アップし、スキルに追撃を発生\nさせる【虚数】を得て隔絶した力で楯突く敵を抹消する。", 133901, 0, 0, 0, "2026/02/15 11:59:59", 0, 1, 0, 6, 0, 3, 133901, 228, 1, 450, 0, 0, "2026/02/09 12:00:00", "クリスティーナ（アルファ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ふぃお", 134001, 2.09, 134001, "【魔法】後衛で、アストルムの冒険へと導くガイド妖精。\nバフとバリアで味方を護りバリアを起点とする攻撃支援、\n風属性の味方への行動速度とＴＰの支援で仲間を支える。", 134001, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 134001, 746, 2, 450, 0, 0, "2026/08/23 12:00:00", "フィオ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ふぶき", 134101, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 5, 1, 3, 134101, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "フブキ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らいらえる", 134201, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 7, 1, 3, 134201, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "ライラエル（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らんふぁ", 134301, 2.09, 134301, "【魔法】後衛で儀装束を纏い精霊と心を通わせる唱喚士。\n敵の数に応じてダメージ量が変化する範囲攻撃や、魔法\n無効バリアなどの支援スキルで想いを詩に乗せ響かせる。", 134301, 0, 0, 0, "2026/03/16 9:59:59", 0, 1, 0, 7, 0, 3, 134301, 778, 2, 450, 0, 0, "2026/03/03 12:00:00", "ランファ（儀装束）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ちか", 134401, 2.09, 134401, "【魔法】後衛で儀装束を纏い歌を紡ぎ伝えていく唱喚士。\n自分と最も近くの味方へ強力なバフとＴＰ回復を行うこと\nで攻撃を支援し、共に心を通わせ美しき旋律を奏でる。", 134401, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 7, 21, 3, 134401, 773, 2, 450, 0, 0, "2025/03/15 15:00:00", "チカ（儀装束）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くろーちぇ", 134501, 2.09, 134501, "【魔法】後衛で超速飛行からの大火力を叩き込むロボ娘。\n上空から速度バフで味方全体を支援しつつ、自分のバリア\nを解除して力へと変え、世界の命運を背負い飛翔する！", 134501, 0, 0, 0, "2026/04/30 11:59:59", 0, 1, 0, 0, 0, 3, 134501, 719, 2, 450, 0, 0, "2026/04/15 12:00:00", "クローチェ（エアリアル）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あおい", 134601, 2.09, 134601, "【物理】中衛で巨大ロボを駆り戦うぼっちのパイロット。\n敵の弱体化や、味方へバリアを展開するスキルを持ち、\n鋼鉄の乙女から放つ光線はいかに堅固な守りも打ち破る。", 134601, 0, 0, 0, "2026/04/30 11:59:59", 0, 1, 0, 35, 35, 3, 134601, 526, 1, 450, 0, 0, "2026/04/15 12:00:00", "アオイ（パイロット）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ほうおう", 134701, 2.09, 134701, "【物理】中衛で、華麗に舞い踊る五色絢爛な煉華の鳳凰。\n攻撃力バフやバリア展開などの攻防支援と、多彩で豊富な\nＨＰ・ＴＰ供給を両立し、浄化の力で皆に安寧を授ける。", 134701, 0, 0, 0, "2026/04/30 11:59:59", 0, 1, 0, 7, 7, 3, 134701, 490, 1, 450, 0, 0, "2026/04/15 12:00:00", "ホウオウ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "つむぎ", 134801, 1.84, 134801, "【物理】中衛から、新たな素材で紡ぐワイルドテーラー。\n最も物攻が高い他の味方へ重複速度アップやＴＰ・攻撃支\n援を仕立て、全体へのＨＰ回復と併せ攻守を両立させる。", 134801, 0, 0, 0, "2026/06/22 11:59:59", 0, 1, 0, 1, 1, 3, 134801, 485, 1, 450, 0, 0, "2026/06/10 12:00:00", "ツムギ（ジオ・ゲヘナ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "かのん", 134901, 2.09, 134901, "【物理】前衛で、おエレガントな高笑いを轟かすド令嬢。\nＵＢや敵からの攻撃で【お堪忍袋】が尽きると逆上し、強\n化されたスキルと行動パターンで華麗におリベンジする。", 134901, 0, 0, 0, "2026/06/22 11:59:59", 0, 1, 0, 2, 0, 3, 134901, 196, 1, 450, 0, 0, "2026/06/10 12:00:00", "カノン");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "えりす", 135001, 2.09, 135001, "【魔法】後衛で、永く夢見た本物の夏に咲き綻ぶ黒薔薇。\n【いばらの冠】の呪縛は再臨により解き放たれ、調和状態\nや攻防支援、回復効果を施し、月下の浜辺に静かに佇む。", 135001, 0, 0, 0, "2026/07/15 11:59:59", 0, 1, 0, 7, 21, 3, 135001, 785, 2, 450, 0, 0, "2026/07/03 12:00:00", "エリス（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しぇふぃ", 135101, 2.09, 135101, "【物理】前衛で盛夏の白波を華麗に乗りこなす氷竜少女。\n敵全体を挑発し、被弾で溜まる【ぐずぐず】をＵＢで発散\nすることで周囲に攻撃支援と天真爛漫な笑顔を振りまく。", 135101, 0, 0, 0, "2026/07/15 11:59:59", 0, 1, 0, 4, 4, 3, 135101, 143, 1, 450, 0, 0, "2026/07/03 12:00:00", "シェフィ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぷれしあ", 135201, 2.09, 135201, "【魔法】中衛で夏の食を満喫し、ぷかぷか漂う天然少女。\nＴＰ・攻撃支援やバリアは味方の数で効果量が変化し、物\n理と魔法攻撃力合算のダメージで夏の思い出を心に刻む。", 135201, 0, 0, 0, "2026/07/15 11:59:59", 0, 1, 0, 7, 7, 3, 135201, 548, 2, 450, 0, 0, "2026/07/03 12:00:00", "プレシア（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くりあ", 135301, 2.09, 135301, "【物理】中衛で友情の芽を育む、真夏の『普通』の少女。\n【プルメリアのお守り】で強力な一撃から先頭を守り、味\n方の数で効果量が変化するスキルを鮮やかに命中させる。", 135301, 0, 0, 0, "2026/08/15 11:59:59", 0, 1, 0, 54, 54, 3, 135301, 413, 1, 450, 0, 0, "2026/07/31 12:00:00", "クリア（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あねもね", 135401, 2.09, 135401, "【魔法】中衛で砂浜の木陰に微睡むアルラウネの妖魔人。\n行動速度アップや初回発動時に回復量が増加するＴＰ回復\nを起点に支援し、穏やかな木漏れ日と共にゆらゆら憩う。", 135401, 0, 0, 0, "2026/08/15 11:59:59", 0, 1, 0, 2, 52, 3, 135401, 553, 2, 450, 0, 0, "2026/07/31 12:00:00", "アネモネ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あいら", 135501, 2.09, 135501, "【物理】前衛で、世界を守り笑顔を咲かせる情熱の豪炎。\n前方の敵全てを対象とする連撃の強化通常攻撃や、天楼覇\n断剣から放たれる極大ダメージの一閃で未来を切り拓く。", 135501, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 1, 0, 3, 135501, 213, 1, 450, 0, 0, "2026/08/23 12:00:00", "アイラ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しなつ", 135601, 0.4, 135601, "【物理】前衛から、風裂く刃で世界を護る孤高の剣豪。\n卓越した剣技で敵の攻撃を捌いて反撃し、初回ＵＢで生成\nする分身と共に疾風迅雷の攻めで、未来へと駆け抜ける。", 135601, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 4, 0, 3, 135601, 198, 1, 450, 0, 0, "2026/08/23 12:00:00", "シナツ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ひより", 135701, 1.84, 135701, "【物理】前衛で、二人きりの月下の空旅にときめく黒猫。\n物防弱体の他、ダメージ100ヒット後には華麗なステップ\nの追撃とＴＰ回復量増加で、砂漠の夜空に花を咲かせる。", 135701, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 1, 0, 3, 135701, 291, 1, 450, 0, 0, "2025/09/16 15:00:00", "ヒヨリ（サラサリア）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆきの", 135801, 2.09, 135801, "【魔法】後衛から、雪魄氷姿の三味を弾じる初心な雪女。\n多様なデバフ効果で敵を弱体化させ、最も魔防の低い敵の\n状態に応じて発生する追加効果で、冥府を真白に染める。", 135801, 0, 0, 0, "2026/10/15 11:59:59", 0, 1, 0, 7, 0, 3, 135801, 830, 2, 450, 0, 0, "2026/09/30 12:00:00", "ユキノ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "さつき", 135901, 1.84, 135901, "【物理】前衛で、華奢な体躯に厚い仁義を宿す鬼のお嬢。\n攻防自己強化や行動不能無効化で豪胆に立ち続け、自分が\n呪詛状態の時に振るう追加攻撃で、怪力無双の力を示す。", 135901, 0, 0, 0, "2026/10/15 11:59:59", 0, 1, 0, 3, 0, 3, 135901, 219, 1, 450, 0, 0, "2026/09/30 12:00:00", "サツキ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あらくね", 136001, 2.09, 136001, "【物理】後衛で、喪われた光を求めてもがく元『六凶』。\n敵のＵＢを遅延する【遮絶の操糸】や、味方単体のＵＢを\n連続発動可能にする【賦活の糸】を戦場に張り巡らせる。", 136001, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 11, 0, 3, 136001, 732, 1, 450, 0, 0, "2026/08/23 12:00:00", "アラクネ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "さくら", 136101, 1.74, 136101, "【物理】中衛で不運に抗い歌い続けるゾンビィアイドル。\n一度倒れても立ち上がり、ＴＰを糧に強化されるスキルの\nダメージと味方の支援で、サガの心をアストルムに刻む。", 136101, 0, 0, 1, "2025/11/03 11:59:59", 0, 1, 0, 0, 0, 3, 136101, 432, 1, 450, 0, 0, "2025/10/24 12:00:00", "サクラ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "なーな", 136201, 2.09, 136201, "【物理】前衛でダメダメでも逃げず戦うアルミラージ娘。\n最も近くの味方に強化や行動不能無効の付与、回復を行い\n敵の注意をそらすことで、過酷な世界を生き延びる。", 136201, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 3, 3, 3, 136201, 198, 1, 450, 0, 0, "2025/11/14 15:00:00", "ナーナ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "みそら", 136301, 2.09, 136301, "【魔法】後衛で、シゲキ的な聖夜に鼓動高鳴る溌溂少女★\n【イルミネーションバレット】を消費して味方を支援し、\n40消費後は追加の範囲攻撃やバフでキュン★を届ける。", 136301, 0, 0, 0, "2026/07/15 11:59:59", 0, 1, 0, 35, 54, 3, 136301, 655, 2, 450, 0, 0, "2026/07/03 12:00:00", "ミソラ（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆい", 136401, 1.84, 136401, "【魔法】中衛で、騎士の隣に一歩踏み出す聖夜の魔法士。\n敵の注目を集めながら攻防支援を行い【聖夜の愛慕】が\n高まると、ＴＰ支援やダメージカットで優しく包み込む。", 136401, 0, 0, 0, "2026/07/15 11:59:59", 0, 1, 0, 7, 21, 3, 136401, 382, 2, 450, 0, 0, "2026/07/03 12:00:00", "ユイ（クリスマス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しずる", 136501, 2.09, 136501, "【物理】前衛で、凛然と立ちはだかる新年のお姉ちゃん。\n挑発と行動不能無効で攻撃を鮮やかに捌き、状況に応じて\n物理・魔法を自在に操り、弟くんへの愛を見せつける。", 136501, 0, 0, 0, "2026/08/23 11:59:59", 0, 1, 0, 5, 0, 3, 136501, 151, 1, 450, 0, 0, "2026/08/15 12:00:00", "シズル（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "めどぅーさ", 136601, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 1, 1, 1, 136601, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "メドゥーサ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らびりすた", 136701, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 8, 1, 3, 136701, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "ラビリスタ（アルファ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らんふぁ", 136801, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 7, 1, 3, 136801, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "ランファ（儀装束）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "るるぃ", 136901, 2.09, 136901, "【物理】中衛でうねる、珍味な触手の小姓見習いタコ娘。\nＴＰ回復、継続ＨＰ回復、バリアで味方をもてなし、多様\nな弱体効果を与える自慢の墨で、敵を真っ黒に染める。", 136901, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 3, 0, 3, 136901, 409, 1, 450, 0, 0, "2026/05/22 12:00:00", "ルルィ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "にのん", 137101, 2.09, 137101, "【魔法】中衛で陽光の下、煌く水面を共に駆けるシノビ。\n【水遁の印】を自らの攻撃力へと変え、束縛フィールドと\n水遁の術で最も遠い敵とその周囲に速やかな天誅を下す。", 137101, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 8, 47, 3, 137101, 566, 2, 450, 0, 0, "2025/08/15 15:00:00", "ニノン（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らびりすた", 137201, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 2, 2, 3, 137201, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "ラビリスタ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "かのん", 137301, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 2, 1, 3, 137301, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "カノン");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "かすみ", 137401, 2.09, 137401, "【魔法】後衛で、聖なる光に包まれ微笑み祈るシスター。\n攻防デバフを操り【真実の導き】が集まると最大３キャラ\nへの攻撃が最も魔防の低い敵を追及し、真理を照らす。", 137401, 0, 0, 0, "2026/06/22 11:59:59", 0, 1, 0, 7, 21, 3, 137401, 688, 2, 450, 0, 0, "2026/06/10 12:00:00", "カスミ（シスター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あいら", 137501, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 3, 137501, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "アイラ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "こっころ", 137601, 2.09, 137601, "【魔法】後衛で、主さまを想い“進化”した嚮導の巫女。\n極大ダメージのＵＢで敵を穿ち、【進化超越】の権能によ\nって、味方のバフやダメージを、限界を超え成長させる。", 137601, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 7, 0, 3, 137601, 733, 2, 450, 0, 0, "2026/08/23 12:00:00", "コッコロ（嚮導幼君）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆきの", 137801, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 7, 1, 3, 137801, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "ユキノ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "りの", 137901, 2.09, 137901, "【魔法】後衛で絵馬に込めた想いを胸に抱く晴れ着の妹。\nクリティカル時に威力が上がる矢で敵を撃ち抜き、味方\n全体への攻撃支援や継続ＴＰ回復で厄を払い福を届ける。", 137901, 0, 0, 0, "2026/08/23 11:59:59", 0, 1, 0, 8, 8, 3, 137901, 684, 2, 450, 0, 0, "2026/08/15 12:00:00", "リノ（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "うぁいおれっと", 138001, 2.09, 138001, "【物理】前衛から慈愛の心で冥府を包む彼岸の屍姫。\nＵＢは敵全体を呑み込む割合ダメージを与え、【冥海の加\n護】を消費して味方の攻防ダウン効果までも禊ぎ清める。", 138001, 0, 0, 0, "2026/09/22 11:59:59", 0, 1, 0, 0, 0, 3, 138001, 154, 1, 450, 0, 0, "2026/09/10 12:00:00", "ヴァイオレット（イサナミ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "らいらえる", 138101, 2.09, 138101, "【魔法】後衛で、民とハーモニーを奏でる天使の姫君。\nステータスアップ効果を受け【エクスマキナ】が溜まると\n行動パターンが変化し、絶え間ない弓撃で神威を示す。", 138101, 0, 0, 0, "2026/09/22 11:59:59", 0, 1, 0, 0, 0, 3, 138101, 729, 2, 450, 0, 0, "2026/09/10 12:00:00", "ライラエル（パルフェクト）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ねふぃーねら", 138201, 2.09, 138201, "【物理】中衛から怯懦を退け、万魔を率する煉獄の鉄媛。\n千変万化の躰は行動速度アップを始めとする多彩な支援と\nすべての敵の弱体を両立し、天地万象を掌の内に収める。", 138201, 0, 0, 0, "2026/09/22 11:59:59", 0, 1, 0, 0, 0, 3, 138201, 502, 1, 450, 0, 0, "2026/09/10 12:00:00", "ネフィ＝ネラ（鬼面仏心）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぺこりーぬ", 138301, 2.09, 138301, "【物理】前衛で女神の血脈と矜持を揮う全力全開の王女。\n物理攻撃力の高い味方を【裁定の盾】で庇い、自身は圧倒\n的な防御とＨＰ回復で前線に立ち幸せな食卓を守り抜く。", 138301, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 138301, 142, 1, 450, 0, 0, "2026/08/23 12:00:00", "ペコリーヌ（アストライア）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "さくら", 138601, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 1, 1, 3, 138601, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "サクラ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "わかな", 138701, 2.09, 138701, "【物理】中衛で恥じらいながらも激戦に飛び込む桃闘者。\n味方を【スパイクシール】で守りつつ、自身は物理防御力\nダウンで敵を切り崩し、鍛え上げた桃尻を存分に振るう。", 138701, 0, 0, 0, "2026/10/15 11:59:59", 0, 1, 0, 7, 55, 3, 138701, 539, 1, 450, 0, 0, "2026/09/30 12:00:00", "ワカナ（ウィンター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しおり", 138801, 2.09, 138801, "【物理】中衛で、過酷なお尻の世界を生き抜く桃闘者。\n攻防ダウンを併せ持つＵＢを矢継ぎ早に放ち、ステータス\nダウン効果で付与する【魅惑の矢】で敵を骨抜きにする。", 138801, 0, 0, 0, "2026/10/15 11:59:59", 0, 1, 0, 8, 8, 3, 138801, 571, 1, 450, 0, 0, "2026/09/30 12:00:00", "シオリ（ウィンター）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぐれいす", 138901, 2.09, 138901, "【物理】中衛で、妖しく跳ねるバニーの幽霊守護騎士。\n物理攻撃力を代償に物理クリダメを極大アップし、【ブラ\nックうさ耳】で油断した敵の虚を突き、御首を頂戴する。", 138901, 0, 0, 0, "2026/04/10 11:59:59", 0, 1, 0, 4, 0, 3, 138901, 429, 1, 450, 0, 0, "2026/03/31 12:00:00", "グレイス（バニー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "きょうか", 139001, 2.09, 139001, "【魔法】後衛で、破滅の運命にあらがうお嬢様？優等生。\n【呪いの鎖】の溢れる魔力で魔防デバフやＴＰ、速度支援\nを行うが、限界を迎えると永久的狂気に陥ってしまう。", 139001, 0, 0, 0, "2026/04/22 11:59:59", 0, 1, 0, 7, 7, 3, 139001, 816, 2, 450, 0, 0, "2026/04/10 12:00:00", "キョウカ（ゴシック）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "きゃる", 139101, 2.09, 139101, "【魔法】後衛で、天の星を瞳に映し、仲間と進む黒猫娘。\n敵全体を激烈に弱体化させながら、【千里真眼】状態時に\n未来を視通す能力で仲間をあらゆる脅威から遠ざける。", 139101, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 139101, 770, 2, 450, 0, 0, "2026/08/23 12:00:00", "キャル（覇瞳天星）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (1, "みほ", 139201, 2.09, 139201, "【魔法】中衛で臨機応変に作戦を指揮する戦車道の乙女。\n召喚したボコが敵の攻撃を引き付けている間に、周囲の\n味方の攻撃、回復支援によって、全員での勝利を目指す。", 139201, 0, 0, 1, "2030/12/31 15:00:00", 0, 1, 0, 0, 0, 1, 139201, 486, 2, 450, 0, 0, "2026/04/30 12:00:00", "ミホ（ガルパン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "まほ", 139301, 2.09, 139301, "【物理】後衛から必中の一射で敵を貫く西住流の継承者。\n【榴弾】を装填した状態のＵＢは、防御力を無視する火傷\nフィールドを発生させ、圧倒的な戦力差で敵を蹂躙する。", 139301, 0, 0, 1, "2026/05/22 11:59:59", 0, 1, 0, 0, 0, 3, 139301, 700, 1, 450, 0, 0, "2026/04/30 12:00:00", "マホ（ガルパン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "えりか", 139401, 1.04, 139401, "【物理】中衛から迅速な強襲で戦局を切り拓く双剣使い。\nバトル開始直後からＴＰを消費する強力なスキルの連撃で\n敵の防御力を一気に下げ、敵陣深くまで浸透突破する。", 139401, 0, 0, 1, "2026/05/22 11:59:59", 0, 1, 0, 0, 0, 3, 139401, 322, 1, 450, 0, 0, "2026/05/11 12:00:00", "エリカ（ガルパン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "りり", 139501, 2.09, 139501, "【魔法】中衛で、寄る辺無き魂を繋ぎ導く清廉の戦乙女。\nダメージと共に敵の魔防を削ぎ、継続ダメージを与える聖\n浄の光が戦乙女の聖槍を降り注がせ、敵を清め祓う。", 139501, 0, 0, 0, "2026/06/10 11:59:59", 0, 1, 0, 0, 0, 3, 139501, 453, 2, 450, 0, 0, "2026/05/31 12:00:00", "リリ（ヴァルキュリア）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くりあ", 139601, 2.09, 139601, "【魔法】前衛で、奇跡により魂の疵を癒す浄罪の戦乙女。\n味方を物理攻撃から堅牢に守り、継続ダメージを与える聖\n浄の光を敵に浴びせ、戦乙女の聖槍による天罰を下す。", 139601, 0, 0, 0, "2026/06/30 11:59:59", 0, 1, 0, 2, 0, 3, 139601, 150, 2, 450, 0, 0, "2026/06/22 12:00:00", "クリア（ヴァルキュリア）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぷれしあ", 139701, 2.09, 139701, "【魔法】中衛で、正義の光で邪な魂を祓う勧善の戦乙女。\n多彩な支援効果で味方を支え、継続ダメージを与える聖浄\nの光が戦乙女の聖槍を喚び寄せ、悪をこらしめる。", 139701, 0, 0, 0, "2026/06/22 11:59:59", 0, 1, 0, 0, 0, 3, 139701, 500, 2, 450, 0, 0, "2026/06/10 12:00:00", "プレシア（ヴァルキュリア）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しぇふぃ", 139801, 2.09, 139801, "【物理】中衛で兄妹の絆と不撓の心で覚醒した氷竜少女。\n個も群も薙ぎ払うＵＢと、【氷竜超克】状態時に発生する\n追撃状態で敵を咬断し、大切な人と歩む未来を切り拓く。", 139801, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 139801, 386, 1, 450, 0, 0, "2026/08/23 12:00:00", "シェフィ（ヴァードラッヘ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "るいずまりー", 139901, 2.09, 139901, "【魔法】後衛で、大人の階段を上りたい水着の錬金術師。\n発動回数で性能が上昇するＵＢとスキルで、調和状態の\n付与と攻防たゆまぬ支援を行い、ひと夏の思い出を創る。", 139901, 0, 0, 0, "2026/07/15 11:59:59", 0, 1, 0, 55, 55, 3, 139901, 757, 2, 450, 0, 0, "2026/07/03 12:00:00", "ルイズマリー（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くれじった", 140001, 2.09, 140001, "【魔法】後衛で、リゾート建設に奔走する水着の女商人。\n初回発動時に強力な攻撃支援と一定時間魔攻・物防・魔防\nダウンを無効化するスキルで、豪奢に味方を駆り立てる。", 140001, 0, 0, 0, "2026/07/31 11:59:59", 0, 1, 0, 54, 54, 3, 140001, 730, 2, 450, 0, 0, "2026/07/15 12:00:00", "クレジッタ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ふぶき", 140101, 2.09, 140101, "【物理】中衛であざとくラヴを奪う超天才びしょーじょ。\n毒と火傷で弱らせた敵をあざ笑うかのように、自分と\n先頭の味方へＴＰ回復や行動不能無効を付与し強化する。", 140101, 0, 0, 0, "2026/08/15 11:59:59", 0, 1, 0, 54, 54, 3, 140101, 376, 1, 450, 0, 0, "2026/07/31 12:00:00", "フブキ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "うぁんぴぃ", 140201, 2.09, 140201, "【魔法】中衛でけんぞくとラヴを集めるつよつよ吸血姫。\nスキルでＴＰを吸収し、【チャームスローブ】を消費して\n放つＵＢは、ほとばしるカワいさで敵を骨抜きにする。", 140201, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 43, 43, 3, 140201, 582, 2, 450, 0, 0, "2026/08/15 12:00:00", "ヴァンピィ（サマー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "てぃあ", 140301, 2.09, 140301, "【魔法】後衛から、中立で平等とうそぶく認識の修正者。\n敵の認識を乱して弱体効果を付与し、一方で味方が受ける\n混乱、誘惑状態を無効化しお気に入りの彼に肩入れする。", 140301, 0, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 140301, 744, 2, 450, 0, 0, "2026/08/23 12:00:00", "ティア");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "りーざ", 140401, 2.09, 140401, "【物理】後衛で、答えを求め彷徨うダークエルフの咎人。\nＵＢで放つ矢の呪いは二度重なれば呪詛、三度重なれば\n強烈な割合ダメージとなり、立ちはだかる敵を殺める。", 140401, 0, 0, 0, "2026/09/22 11:59:59", 0, 1, 0, 0, 0, 3, 140401, 780, 1, 450, 0, 0, "2026/09/10 12:00:00", "リーザ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "うるむ", 140501, 2.09, 140501, "【物理】中衛で、愛する者たちのため本意気を放つ妹竜。\n【決意の流星】を溜め覚醒すると、攻撃スキルが再発動し\nさらに味方の火力を引き上げ、渦炎で敵を灰燼に変える。", 140501, 0, 0, 0, "2026/09/10 11:59:59", 0, 1, 0, 0, 0, 3, 140501, 396, 1, 450, 0, 0, "2026/08/31 12:00:00", "ヴルム（ヴァルムドラッヘ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "くろーちぇ", 140601, 2.09, 140601, "【物理】中衛から必殺クローで敵全体を圧潰するロボ娘。\n自分へのバフと敵へのデバフで【水陸可変ブースター】が\n起動し、高頻度のＵＢでダメージの大渦潮を巻き起こす！", 140601, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 0, 0, 3, 140601, 400, 1, 450, 0, 0, "2026/09/22 12:00:00", "クローチェ（サブマリン）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "されん", 140701, 2.09, 140701, "【物理】中衛で、敵影に照準を定める戦場のサレンママ。\n７種以上の弱体効果があれば更に効果が増すスキルで敵の\n装甲に風穴を開け、臨機応変の戦術で窮地を逆手に取る。", 140701, 0, 0, 0, "2026/10/09 11:59:59", 0, 1, 0, 0, 0, 3, 140701, 431, 1, 450, 0, 0, "2026/09/30 12:00:00", "サレン（ガンナー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しずる", 141401, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 1, 1, 1, 141401, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "シズル（ニューイヤー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "うぁいおれっと", 141501, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 0, 1, 3, 141501, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "ヴァイオレット（イサナミ）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぐれいす", 141601, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 4, 1, 3, 141601, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "グレイス（バニー）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "るいずまりー", 143001, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 0, 1, 3, 143001, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "ルイズマリー");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "じーた", 170101, 1.965, 105701, "【物理】前衛で、先手必勝の大技を繰り出す騎空士。\nスキルによるＴＰ回復は、ユニオンバーストの発動を早め\nバトルの序盤から敵前衛に大ダメージを与える。", 170101, 4, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 34, 34, 3, 170101, 245, 1, 450, 0, 0, "2015/04/01 15:00:00", "ジータ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ひより", 180101, 1.62, 180101, "【物理】前衛で炎翼を背に敵を粉砕する、陽気な元気娘。\n戦いが続く程に自身の攻撃能力を強めるスキルを操り、\n高めた力で放つ超爆の一撃は、あらゆる敵を塵と化す。", 180101, 7, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 180101, 199, 1, 450, 0, 0, "2026/08/23 12:00:00", "ヒヨリ（プリンセス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ゆい", 180201, 1.92, 180201, "【魔法】後衛から極大魔法で敵を滅する願いの魔法士。\nＴＰを回復しつつ攻撃力を累積アップする補助スキルで\n自身の力を高め、強力な範囲攻撃を放ち敵を一掃する。", 180201, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 180201, 767, 2, 450, 0, 0, "2026/08/23 12:00:00", "ユイ（プリンセス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "れい", 180301, 1.965, 180301, "【物理】中衛で風刃を従え激戦を流麗に征く嵐翼の剣士。\n敵が多い程に効果が高まる自己強化スキルで、自身を奮い\n立たせ、強力な範囲攻撃スキルで一切の敵を鏖滅する。", 180301, 7, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 180301, 377, 1, 450, 0, 0, "2026/08/23 12:00:00", "レイ（プリンセス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぺこりーぬ", 180401, 1.965, 180401, "【物理】前衛で、攻防共に絶大な力を誇る腹ペコ王女。\nＨＰが多い時は爆発的な攻撃力で、いかなる敵をも屠り、\nＨＰが減ると自己回復能力を得て、鉄壁の護りを見せる。", 180401, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 180401, 155, 1, 450, 0, 0, "2026/08/23 12:00:00", "ペコリーヌ（プリンセス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "こっころ", 180501, 2.14, 180501, "【物理】中衛で、絶大な補助スキルを繰出す純白の巫女。\n味方の攻撃力とクリティカルダメージを強化しつつ、\n二つの全体回復スキルで味方を堅固に守護し勝利へ導く。", 180501, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 180501, 555, 1, 450, 0, 0, "2026/08/23 12:00:00", "コッコロ（プリンセス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "きゃる", 180601, 1.92, 180601, "【魔法】後衛で、極大魔法を操り敵を討つ姫装の猫娘。\n回復や補助を兼ねた各攻撃スキルを駆使し戦況を整え、\n極大威力のユニオンバーストを撃ち込み敵を燼滅する。", 180601, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 180601, 747, 2, 450, 0, 0, "2026/08/23 12:00:00", "キャル（プリンセス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "はつねしおり", 180701, 1.75, 180701, "【物理】後衛から、真の絆の力を発揮する仲良し姉妹。\n敵の数が増えるほど威力が高まる攻撃スキルと、周りの\n味方を強化するスキルを操り、立ち塞がる敵を一掃する。", 180701, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 180701, 732, 1, 450, 0, 0, "2026/08/23 12:00:00", "ハツネ＆シオリ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "みそぎみみきょうか", 180801, 1.5, 180801, "【物理】中衛で敵単体に必殺の一撃を放つ仲良しトリオ。\n３人の力を合わせて放つ攻撃は、相手の弱点に合わせて\n物理から魔法攻撃に変化し、どんな強い敵も退治する！", 180801, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 180801, 465, 1, 450, 0, 0, "2026/08/23 12:00:00", "ミソギ＆ミミ＆キョウカ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あきのされん", 180901, 2.09, 180901, "【物理】中衛で背を預けあう最高の好敵手で親友の二人。\n味方の物理攻撃をサポートしつつＨＰとＴＰを継続回復し\nＨＰが多いほど威力が増すＵＢで、共に勝利の道を征く。", 180901, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 180901, 421, 1, 450, 0, 0, "2026/08/23 12:00:00", "アキノ＆サレン");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "あんぐれあ", 181001, 2.09, 181001, "【魔法】中衛で、魔力共鳴し連撃を放つマナリアの双姫。\nステータスアップ効果を受けると増加する【友情の魔印】\nがスキルを強化し、波長を合わせた炎の魔槍で敵を討つ。", 181001, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 181001, 577, 2, 450, 0, 0, "2026/08/23 12:00:00", "アン＆グレア");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しずるりの", 181101, 1.92, 181101, "【物理】中衛でお揃い衣装の、真偽を超えた仲良し姉妹。\n攻守共に味方を支えるシズルと、クリティカル時に強力な\nダメージを与えるリノ、姉妹の絆で困難を跳ね除ける！", 181101, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 181101, 551, 1, 450, 0, 0, "2026/08/23 12:00:00", "シズル＆リノ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しぇふぃ", 181201, 1.92, 181201, "【物理】中衛で新たな力と共に再廻する姫装の氷竜少女。\n環境効果【絶氷】でクリティカルダメージを高め、火力と\n手数を併せ持つ剣技で、再び共に歩むため道を切り開く。", 181201, 1, 0, 0, "2026/08/26 11:59:59", 0, 1, 0, 0, 0, 3, 181201, 368, 1, 450, 0, 0, "2026/08/23 12:00:00", "シェフィ（プリンセス）");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "かりん", 190801, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 1, 1, 1, 190801, 0, 1, 0, 0, 0, "2015/04/01 15:00:00", "カリン");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "ぺてるぎうす", 191201, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 1, 1, 1, 191201, 0, 1, 0, 0, 0, "2015/04/01 15:00:00", "ペテルギウス");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "かずまさ", 191301, 2.22, 191301, "【物理】皆から愛される漁師町のポンコツ漁師。\nユニオンバーストは強力なスタン効果を持つが、\n自身のＨＰが50%以下では尻もちをついてしまう。\n\n・通常攻撃とユニオンバーストを駆使して戦う。", 191301, 0, 0, 0, "2030/12/31 15:00:00", 0, 1, 0, 6, 6, 1, 191301, 850, 1, 450, 0, 0, "2015/04/01 15:00:00", "カズマサ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "こっころ", 191401, 0.0, 0, "", 0, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 6, 6, 0, 191401, 0, 0, 0, 0, 0, "2015/04/01 15:00:00", "コッコロ");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しゅじんこう", 191501, 0.0, 100101, "残されたわずかな時間で宿題を終わらせんとする\nルーセント学院の生徒。楽しい夏休みの思い出を\n守るため、山積みの宿題へと立ち向かう。", 100101, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 0, 0, 0, 191501, 1600, 0, 150, 0, 0, "2015/04/01 15:00:00", "主人公");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しゅじんこう", 191601, 0.0, 100101, "残されたわずかな時間で宿題を終わらせんとする\nルーセント学院の生徒。楽しい夏休みの思い出を\n守るため、山積みの宿題へと立ち向かう。", 100101, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 0, 0, 0, 191601, 1600, 0, 150, 0, 0, "2015/04/01 15:00:00", "主人公");
INSERT INTO `v1_72eed14207272e0d9d1649016bfed38f55836b5903f391671de1b08c0ac21aaa` VALUES (0, "しゅじんこう", 191701, 0.0, 100101, "残されたわずかな時間で宿題を終わらせんとする\nルーセント学院の生徒。楽しい夏休みの思い出を\n守るため、山積みの宿題へと立ち向かう。", 100101, 0, 0, 0, "2030/12/31 15:00:00", 0, 0, 0, 0, 0, 0, 191701, 1600, 0, 150, 0, 0, "2015/04/01 15:00:00", "主人公");
